from typing import Protocol, runtime_checkable

class Drawable(Protocol):                         # structural: no inheritance required
    def draw(self, canvas: "Canvas") -> None: ...

def render(items: list[Drawable]) -> None:        # any object with draw() is accepted
    for item in items:
        item.draw(canvas)

